#!/usr/bin/env node
'use strict';

const fs = require('fs');
const path = require('path');

const TODO_PATTERN = /TODO:[^\n]*/g;
const DEFAULT_FILE = 'README.md';

function extractTodoStrings(text) {
  const strings = [];
  const seen = new Set();
  let match;
  TODO_PATTERN.lastIndex = 0;
  while ((match = TODO_PATTERN.exec(text)) !== null) {
    const value = match[0].replace(/\s+$/, '');
    if (!seen.has(value)) {
      seen.add(value);
      strings.push(value);
    }
  }
  return strings;
}

function countOccurrences(haystack, needle) {
  if (!needle) return 0;
  let count = 0;
  let index = haystack.indexOf(needle);
  while (index !== -1) {
    count += 1;
    index = haystack.indexOf(needle, index + needle.length);
  }
  return count;
}
```

