```js
#!/usr/bin/env node
'use strict';

const fs = require('node:fs');
const path = require('node:path');

const DEFAULT_FILE = 'README.md';
const TODO_PATTERN = /TODO:[^\n]*/g;

const USAGE = `Usage: todo-cli [options] [file]

Count how many times each TODO string occurs in a document, including the
line that declares it. Matching is literal ("as written").

Options:
  -f, --file <path>  document to scan (default: ${DEFAULT_FILE})
  --json             output results as JSON
  -h, --help         show this help
  -v, --version      show the version
  -                  read the document from stdin
`;
```

Then:

```js
function parseArgs(argv) {
  const options = { file: null, json: false, help: false, version: false };
  const rest = [];
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    switch (arg) {
      case '-h':
      case '--help':
        options.help = true;
        break;
      case '-v':
      case '--version':
        options.version = true;
        break;
      case '--json':
        options.json = true;
        break;
      case '-f':
      case '--file':
        i += 1;
        if (i >= argv.length) throw new Error(`${arg} requires a path`);
        options.file = argv[i];
        break;
      case '-':
        options.file = '-';
        break;
      default:
        if (arg.startsWith('-') && arg !== '-') throw new Error(`Unknown option: ${arg}`);
        rest.push(arg);
    }
  }
  if (rest.length > 1) throw new Error('Only one document may be given');
  if (rest.length === 1 && !options.file) options.file = rest[0];
  return options;
}
```

