computeCounts(text) → array of {todo, count}.

format: text lines `${todo}: ${count}`; json: JSON.stringify(obj, null, 2).

Main:
```js
function main(argv) {
  const options = parseArgs(argv);
  if (options.help) { process.stdout.write(USAGE); return 0; }
  if (options.version) { process.stdout.write(`${VERSION}\n`); return 0; }
  const file = options.file || DEFAULT_FILE;
  let text;
  try { text = readDocument(file); }
  catch (err) { process.stderr.write(`todo-cli: cannot read ${file}: ${err.message}\n`); return 1; }
  const counts = computeCounts(text);
  if (options.json) {
    const out = {};
    for (const { todo, count } of counts) out[todo] = count;
    process.stdout.write(`${JSON.stringify(out, null, 2)}\n`);
  } else {
    for (const { todo, count } of counts) process.stdout.write(`${todo}: ${count}\n`);
  }
  return 0;
}

if (require.main === module) {
  try {
    process.exitCode = main(process.argv.slice(2));
  } catch (err) {
    process.stderr.write(`todo-cli: ${err.message}\n`);
    process.exitCode = 1;
  }
}

module.exports = { computeCounts, countOccurrences, extractTodoStrings, formatCounts, main };
```

